import type { Student } from './student-model';
import type { Skill } from './skill-model';

export const StudentSkillProficiencyKeyToLabel = {
  'ProficiencyKey0': 'Beginner',
  'ProficiencyKey1': 'Intermediate',
  'ProficiencyKey2': 'Advanced'
} as const;
export type StudentSkillProficiencyKey = keyof typeof StudentSkillProficiencyKeyToLabel;

export interface StudentSkill {
  /**
   * @displayName Student Skill ID
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Student Skill Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  studentSkillName: string;
  /**
   * @displayName Proficiency
   * @validationRule Required for create/update operations
   */
  proficiencyKey: StudentSkillProficiencyKey;
  /**
   * @displayName Skill
   * @validationRule Required for create/update operations
   */
  skill: Pick<Skill, 'id' | 'name1'>;
  /**
   * @displayName Student
   * @validationRule Required for create/update operations
   */
  student: Pick<Student, 'id' | 'name1'>;
  /**
   * @displayName Verified
   * @validationRule Required for create/update operations
   */
  verified: boolean;
}

export const _StudentSkill = 'StudentSkill' as const;

